/**
 * PSE Insider Filings Provider
 *
 * Reads data/pse-insider-filings.json (generated by
 * scripts/scrape-pse-insider-filings.ts, which scrapes real form 17-7
 * "Statement of Changes in Beneficial Ownership of Securities" filings —
 * see PSEEdgeScraper.ts's ParsedInsiderFiling doc for what fields are
 * real vs deliberately omitted).
 *
 * No synthetic fallback: a symbol with no scraped filings gets an empty
 * array, and the UI should render an honest "no recent insider filings"
 * state rather than the fabricated MOCK_FILINGS data this replaces.
 */
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

export interface PseInsiderFilingRecord {
  symbol: string;
  reportingPerson: string | null;
  relationship: string | null;
  description: string | null;
  filingDate: string;
  edgeNo: string;
  sourceUrl: string;
  scrapedAt: string;
}

type InsiderFilingsMap = Record<string, PseInsiderFilingRecord[]>;

let cache: InsiderFilingsMap | null = null;

function loadMap(): InsiderFilingsMap {
  if (cache !== null) return cache;
  let loaded: InsiderFilingsMap = {};
  try {
    const raw = readFileSync(resolve(process.cwd(), 'data/pse-insider-filings.json'), 'utf-8');
    loaded = JSON.parse(raw).results ?? {};
  } catch {
    // File not generated yet — no real data.
  }
  cache = loaded;
  return loaded;
}

/** Real recent insider filings for a symbol, or an empty array if none
 * are available. Never fabricated. */
export function loadPseInsiderFilings(symbol: string): PseInsiderFilingRecord[] {
  return loadMap()[symbol.toUpperCase()] ?? [];
}
